const header = String(($json.headers ?? {})['x-lendloop-signature'] ?? '');
const payload = typeof $json.body?.payload === 'string' ? $json.body.payload : '';
const m = /^t=(\d{1,12}),v1=([0-9a-f]{64})$/.exec(header);
const t = m ? Number(m[1]) : 0;
const fresh = !!m && Math.abs(Math.floor(Date.now() / 1000) - t) <= 300 && payload.length > 0 && payload.length <= 5000;
return { json: { t, given: m ? m[2] : '', payload, fresh, toSign: t + '.' + payload } };

const a = String($json.v1 ?? '');
const b = String($json.given ?? '');
let diff = (a.length === 64 && b.length === 64) ? 0 : 1;
for (let i = 0; i < 64; i += 1) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
if (diff !== 0 || $json.fresh !== true) return { json: { valid: false } };
let p;
try { p = JSON.parse($json.payload); } catch (e) { return { json: { valid: false } }; }
const types = ['request_created', 'request_approved', 'request_declined'];
const iso = /^\d{4}-\d{2}-\d{2}$/;
const ok = p && types.includes(p.type) && /^evt_[0-9a-f-]{36}$/.test(String(p.eventId)) && typeof p.recipientEmail === 'string' && p.recipientEmail.length <= 254 && /^[^\s@,;]+@[^\s@,;]+$/.test(p.recipientEmail) && iso.test(String(p.startDate)) && iso.test(String(p.endDate));
if (!ok) return { json: { valid: false } };
const clean = (x, n) => String(x ?? '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, n);
const day = (d) => new Date(d + 'T00:00:00Z').toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'UTC' });
const name = clean(p.recipientFirstName, 50) || 'there';
const other = clean(p.otherFirstName, 50) || 'A neighbour';
const tool = clean(p.toolName, 60) || 'your tool';
const range = day(p.startDate) + ' to ' + day(p.endDate);
let subject = '';
let text = '';
if (p.type === 'request_created') {
  subject = other + ' would like to borrow your ' + tool;
  text = 'Hi ' + name + ',\n\n' + other + ' would like to borrow your ' + tool + ' from ' + range + '.\n\nOpen LendLoop to say yes or no. There is no rush, and saying no is completely fine.\n\nLendLoop';
} else if (p.type === 'request_approved') {
  subject = other + ' said yes: ' + tool;
  text = 'Hi ' + name + ',\n\nGood news: ' + other + ' is happy to lend you the ' + tool + ' from ' + range + '.\n\nOpen LendLoop to see how to reach ' + other + ' and arrange pick-up.\n\nLendLoop';
} else {
  subject = 'About your request for the ' + tool;
  text = 'Hi ' + name + ',\n\n' + other + " can't lend the " + tool + ' on those dates this time. That happens, and it is nothing personal.\n\nThere may be something similar on the board. Have a look on LendLoop.\n\nLendLoop';
}
return { json: { valid: true, eventId: p.eventId, type: p.type, to: p.recipientEmail, subject, text } };
